  "witnessCode": "import { strict as assert } from 'node:assert';
import { test } from 'node:test';
import x from '../index.js'  // default export: function(urlString, options)

test('keepQueryParameters: [] should preserve all query parameters', () => {
  const url = 'http://example.com?foo=bar&baz=qux';
  const options = { keepQueryParameters: [] };
  const result = x(url, options);
  const expected = 'http://example.com?foo=bar&baz=qux';
  assert.strictEqual(result, expected);
});"
